<div class="section-title"><div><h1>Recommended matches</h1><p class="muted">For lost report: <?= h($source['title']) ?></p></div><a class="btn btn-secondary" href="<?= h(url('find_matches.php?id=' . $id)) ?>">Run matching again</a></div>
<div class="notice"><strong>Important:</strong> Similarity scores are suggestions only. A high score does not prove ownership.</div>
<?php if (!$matches): ?><div class="card empty section">No saved matches. Run matching to generate recommendations.</div><?php else: ?><section class="section item-grid"><?php foreach ($matches as $match): $components = json_decode($match['components_json'] ?? '{}', true) ?: []; ?><article class="item-card"><img src="<?= h(item_image_url($match['image_path'])) ?>" alt=""><div class="item-card-body"><div class="meta"><span><?= h($match['engine']) ?></span><?= status_badge($match['status']) ?></div><h3><?= h($match['title']) ?></h3><div class="score"><?= h(number_format((float)$match['score'], 1)) ?>%</div><div class="progress" aria-label="Match score"><span style="width:<?= min(100, max(0, (float)$match['score'])) ?>%"></span></div><p><?= h(mb_strimwidth($match['description'], 0, 100, '…')) ?></p><div class="component-list"><?php foreach ($components as $name => $value): ?><div class="component"><strong><?= h(ucfirst($name)) ?></strong><br><?= h(number_format((float)$value, 0)) ?>%</div><?php endforeach; ?></div><div class="form-actions"><a class="btn btn-small" href="<?= h(url('item.php?id=' . $match['candidate_item_id'])) ?>">View item</a><?php if ($match['status'] === 'open'): ?><a class="btn btn-secondary btn-small" href="<?= h(url('create_claim.php?lost=' . $id . '&found=' . $match['candidate_item_id'])) ?>">Submit claim</a><?php endif; ?></div></div></article><?php endforeach; ?></section><?php endif; ?>
